// Break on paragraph, then word, then hard-cut — so blocks split where a human would.
const chunkText = (text, size) => {
  const chunks = [];
  let rest = text;
  while (rest.length > size) {
    let cut = rest.lastIndexOf('\n', size);
    if (cut < size * 0.5) cut = rest.lastIndexOf(' ', size);
    if (cut < size * 0.5) cut = size;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) chunks.push(rest);
  return chunks;
};

const paragraph = (content) => ({
  object: 'block',
  type: 'paragraph',
  paragraph: { rich_text: [{ type: 'text', text: { content } }] },
});

const richText = (content) => ({ rich_text: [{ type: 'text', text: { content: String(content) } }] });

return $input.all().map((item) => {
  const cfg = item.json;
  const body = cfg.body ?? {};
  const has = (k) => Object.prototype.hasOwnProperty.call(body, k);
  const errors = [];

  const captureId = String(body.captureId ?? '').trim();
  // captureId is the only hard requirement now: an update may legitimately
  // carry nothing but the key and the one field it is changing.
  if (!captureId) errors.push('captureId is required');

  const transcript = has('transcript') && body.transcript !== null
    ? String(body.transcript).trim()
    : '';

  const createProperties = {};
  const updateProperties = {};
  const setBoth = (name, shape) => {
    createProperties[name] = shape;
    updateProperties[name] = shape;
  };

  // --- Capture ID: always present by definition, always written -------------
  setBoth('Capture ID', richText(captureId));

  // --- Name -----------------------------------------------------------------
  let title = '';
  if (has('title') && body.title !== null && String(body.title).trim()) {
    title = String(body.title).trim();
  } else if (transcript) {
    title = transcript.split(/(?<=[.!?])\s/)[0] || transcript;
  }
  if (title.length > MAX_TITLE_CHARS) {
    title = title.slice(0, MAX_TITLE_CHARS - 1).trimEnd() + '…';
  }
  // A new page always gets a name; an existing page keeps its own unless the
  // caller explicitly sent a title.
  createProperties['Name'] = { title: [{ type: 'text', text: { content: title || captureId } }] };
  if (has('title')) {
    updateProperties['Name'] = body.title === null
      ? CLEAR.title
      : { title: [{ type: 'text', text: { content: title || captureId } }] };
  }

  // --- Filename -------------------------------------------------------------
  if (has('filename')) {
    setBoth('Filename', body.filename === null ? CLEAR.rich_text : richText(body.filename));
  }

  // --- Device ---------------------------------------------------------------
  if (has('device')) {
    const raw = body.device === null ? '' : String(body.device).trim();
    if (!raw) {
      setBoth('Device', CLEAR.select);
    } else {
      const lower = raw.toLowerCase();
      const hit = DEVICE_OPTIONS.find(([fragment]) => lower.includes(fragment));
      setBoth('Device', { select: { name: hit ? hit[1] : 'Other' } });
    }
  }

  // --- Duration (s) ---------------------------------------------------------
  if (has('duration')) {
    const seconds = parseDuration(body.duration);
    setBoth('Duration (s)', seconds === null ? CLEAR.number : { number: seconds });
  }

  // --- Size (MB): bytes in, megabytes stored --------------------------------
  if (has('size')) {
    const mb = parseSizeMb(body.size);
    setBoth('Size (MB)', mb === null ? CLEAR.number : { number: mb });
  }

  // --- Word Count: derived, so it moves only when transcript is sent --------
  let wordCount = 0;
  if (has('transcript')) {
    wordCount = transcript ? transcript.split(/\s+/).filter(Boolean).length : 0;
    setBoth('Word Count', body.transcript === null ? CLEAR.number : { number: wordCount });
  }

  // --- Captured At: explicit field wins, captureId prefix is the fallback ---
  // Both paths go through toZonedIso, so nothing reaches Notion without an
  // offset and no capture drifts by the UTC gap.
  const timeZone = cfg.captureTimeZone || 'America/Chicago';
  const parsedAt = toZonedIso(capturedAtFromId(captureId), timeZone);
  if (has('capturedAt')) {
    const explicit = body.capturedAt === null ? null : toZonedIso(body.capturedAt, timeZone);
    if (body.capturedAt !== null && String(body.capturedAt).trim() && !explicit) {
      errors.push(`capturedAt is not a recognizable date: ${String(body.capturedAt).trim()}`);
    }
    setBoth('Captured At', explicit ? { date: { start: explicit } } : CLEAR.date);
  } else if (parsedAt) {
    // Fallback feeds the create path only. captureId is on every request, so
    // deriving into updateProperties would overwrite a hand-edited date forever.
    createProperties['Captured At'] = { date: { start: parsedAt } };
  }

  // --- First-write defaults: create only ------------------------------------
  createProperties['Status'] = { select: { name: cfg.defaultStatus || 'Inbox' } };
  createProperties['Source'] = { select: { name: cfg.defaultSource || 'iOS Shortcut' } };

  // --- Page body ------------------------------------------------------------
  const device = createProperties['Device']?.select?.name ?? null;
  const meta = [
    device,
    has('duration') && createProperties['Duration (s)']?.number != null
      ? `${createProperties['Duration (s)'].number}s` : null,
    has('size') && createProperties['Size (MB)']?.number != null
      ? `${createProperties['Size (MB)'].number} MB` : null,
    wordCount ? `${wordCount} words` : null,
  ].filter(Boolean).join('  ·  ');

  const children = [{
    object: 'block',
    type: 'callout',
    callout: {
      icon: { emoji: '📱' },
      color: 'gray_background',
      rich_text: [{ type: 'text', text: { content: [captureId, meta].filter(Boolean).join('  ·  ') } }],
    },
  }];

  let overflow = [];
  let updateBlocks = [];
  if (transcript) {
    children.push({
      object: 'block',
      type: 'heading_2',
      heading_2: { rich_text: [{ type: 'text', text: { content: 'Transcript' } }] },
    });
    const chunks = chunkText(transcript, MAX_BLOCK_CHARS).map(paragraph);
    children.push(...chunks.slice(0, MAX_CHILDREN));
    // Beyond ~370k characters the transcript is genuinely cut; say so on the page
    // rather than dropping it silently, and keep the append batch at Notion's 100.
    if (chunks.length > MAX_CHILDREN + MAX_OVERFLOW) {
      overflow = chunks.slice(MAX_CHILDREN, MAX_CHILDREN + MAX_OVERFLOW - 1);
      overflow.push(paragraph('⚠️ Transcript truncated — exceeded the Notion block ceiling for one capture.'));
    } else {
      overflow = chunks.slice(MAX_CHILDREN);
    }
    updateBlocks = chunks.slice(0, MAX_UPDATE_BLOCKS);
  }

  // Updates never rewrite page children. Blocks are appended only on an
  // explicit opt-in, otherwise every re-send would duplicate the transcript.
  const appendOnUpdate = body.appendBlocks === true && updateBlocks.length > 0;

  return {
    json: {
      valid: errors.length === 0,
      errors,
      captureId,
      capturedAt: createProperties['Captured At']?.date?.start ?? null,
      title,
      wordCount,
      notionDatabaseId: cfg.notionDatabaseId,
      notionVersion: cfg.notionVersion,
      createProperties,
      updateProperties,
      children,
      overflow,
      updateBlocks,
      appendOnUpdate,
      hasOverflow: overflow.length > 0,
    },
  };
});

