    setBoth('Captured At', explicit ? { date: { start: explicit } } : CLEAR.date);
  } else if (parsedAt) {
    // Fallback feeds the create path only. captureId is on every request, so
    // deriving into updateProperties would overwrite a hand-edited date forever.
    createProperties['Captured At'] = { date: { start: parsedAt } };
  }

  // --- First-write defaults: create only ------------------------------------
  createProperties['Status'] = { select: { name: cfg.defaultStatus || 'Inbox' } };
  createProperties['Source'] = { select: { name: cfg.defaultSource || 'iOS Shortcut' } };

  // --- Page body ------------------------------------------------------------
  const device = createProperties['Device']?.select?.name ?? null;
  const meta = [
    device,
    has('duration') && createProperties['Duration (s)']?.number != null
      ? `${createProperties['Duration (s)'].number}s` : null,
    has('size') && createProperties['Size (MB)']?.number != null
      ? `${createProperties['Size (MB)'].number} MB` : null,
    wordCount ? `${wordCount} words` : null,
  ].filter(Boolean).join('  ·  ');

  const children = [{
    object: 'block',
    type: 'callout',
    callout: {
      icon: { emoji: '📱' },
      color: 'gray_background',
      rich_text: [{ type: 'text', text: { content: [captureId, meta].filter(Boolean).join('  ·  ') } }],
    },
  }];

  let overflow = [];
  let updateBlocks = [];
  if (transcript) {
    children.push({
      object: 'block',
      type: 'heading_2',
      heading_2: { rich_text: [{ type: 'text', text: { content: 'Transcript' } }] },
    });
    const chunks = chunkText(transcript, MAX_BLOCK_CHARS).map(paragraph);
    children.push(...chunks.slice(0, MAX_CHILDREN));
    // Beyond ~370k characters the transcript is genuinely cut; say so on the page
    // rather than dropping it silently, and keep the append batch at Notion's 100.
    if (chunks.length > MAX_CHILDREN + MAX_OVERFLOW) {
      overflow = chunks.slice(MAX_CHILDREN, MAX_CHILDREN + MAX_OVERFLOW - 1);
      overflow.push(paragraph('⚠️ Transcript truncated — exceeded the Notion block ceiling for one capture.'));
    } else {
      overflow = chunks.slice(MAX_CHILDREN);
    }
    updateBlocks = chunks.slice(0, MAX_UPDATE_BLOCKS);
  }

  // Updates never rewrite page children. Blocks are appended only on an
  // explicit opt-in, otherwise every re-send would duplicate the transcript.
  const appendOnUpdate = body.appendBlocks === true && updateBlocks.length > 0;

  return {
    json: {
      valid: errors.length === 0,
      errors,
      captureId,
      capturedAt: createProperties['Captured At']?.date?.start ?? null,
      title,
      wordCount,
      notionDatabaseId: cfg.notionDatabaseId,
      notionVersion: cfg.notionVersion,
      createProperties,
      updateProperties,
      children,
      overflow,
      updateBlocks,
      appendOnUpdate,
      hasOverflow: overflow.length > 0,
    },
  };
});
